import{bV as a,aL as e,u as d,G as o}from"./chunks/framework.DvBUyM1S.js";const g=JSON.parse('{"title":"个人可复用知识库（changelog）","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),n={name:"README.md"};function r(s,t,l,i,h,c){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="个人可复用知识库-changelog" tabindex="-1">个人可复用知识库（changelog） <a class="header-anchor" href="#个人可复用知识库-changelog" aria-label="Permalink to &quot;个人可复用知识库（changelog）&quot;">​</a></h1><blockquote><p>人可读、agent 可检索、进 git、跨工具共享的沉淀仓库。 由 AI 会话中的 auto-changelog 流程自动维护，人也随时可用。</p></blockquote><h2 id="现状速览" tabindex="-1">现状速览 <a class="header-anchor" href="#现状速览" aria-label="Permalink to &quot;现状速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>数量</th><th>说明</th></tr></thead><tbody><tr><td>prompts</td><td>3</td><td>可直接复制使用的提示词 / 模板</td></tr><tr><td>playbooks</td><td>27</td><td>实战手册（步骤 + 命令 + 坑点）</td></tr><tr><td>learnings</td><td>8</td><td>单点认知：纠正 / 缺口 / 更好做法</td></tr><tr><td>errors</td><td>35</td><td>命令失败、集成故障、踩坑记录</td></tr></tbody></table><p>数字可能与实际有漂移，以 <a href="./">INDEX.md</a> 为准。</p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>想做什么</th><th>去哪</th></tr></thead><tbody><tr><td>找内容</td><td><a href="./">INDEX.md</a>（总索引，唯一入口）</td></tr><tr><td>写入 / 整合新条目</td><td><a href="./WORKFLOW">WORKFLOW.md</a>（类型路由、格式契约、七步流程）</td></tr><tr><td>校验一致性</td><td><code>tools/sync-index.ps1</code>（退出码 0 即通过）</td></tr><tr><td>重建索引</td><td><code>tools/sync-index.ps1 -Sync</code>（以 frontmatter 为真相源）</td></tr></tbody></table><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prompts/       可直接复制使用的提示词模板（单文件 + frontmatter）</span></span>
<span class="line"><span>playbooks/     实战验证过的操作手册（步骤 + 命令 + 坑点）</span></span>
<span class="line"><span>learnings/     分轨追加日志：</span></span>
<span class="line"><span>               ERRORS.md            踩坑记录</span></span>
<span class="line"><span>               LEARNINGS.md         单点认知</span></span>
<span class="line"><span>               FEATURE_REQUESTS.md  想要而还没有的能力</span></span>
<span class="line"><span>skills/        第三方技能资产（self-improving-agent 完整体系）</span></span>
<span class="line"><span>archive/       历史归档（含旧版规则 auto-changelog-v1）</span></span></code></pre></div><h2 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h2><p><strong>人</strong>：打开 <code>INDEX.md</code>，按 tags / title 定位 → 读对应文件。playbook 直接照步骤执行。</p><p><strong>agent</strong>：会话中遇到可复用产出时按 <code>WORKFLOW.md</code> 七步流程写入；检索时先读 <code>INDEX.md</code> 再读条目，不凭记忆猜测条目内容。</p><h2 id="维护约定-摘要" tabindex="-1">维护约定（摘要） <a class="header-anchor" href="#维护约定-摘要" aria-label="Permalink to &quot;维护约定（摘要）&quot;">​</a></h2><ul><li><strong>触发</strong>：产出可脱离原对话独立使用的内容（完整步骤 / 命令 / 提示词模板 / 踩坑修复），或用户明示「整合 / 保存 / 沉淀 / 提交」；纯闲聊、一次性结论、项目特定细节不触发。</li><li><strong>格式</strong>：单文件条目带完整 frontmatter（id / type / title / tags / status / source / created / updated）；分轨条目按固定 markdown 结构追加。</li><li><strong>判重</strong>：写入前必查 <code>INDEX.md</code>，已有同类条目则更新原文件并刷新 <code>updated</code>，禁止建重复文件。</li><li><strong>git</strong>：只 add 本次写入的精确文件列表（含 INDEX.md），禁 <code>add -A</code>；commit 后 push，不 force push、不改历史。</li><li><strong>红线</strong>：凭证 / 密钥 / token、内部 IP / 域名、未脱敏客户数据，永不入库。</li></ul><h2 id="晋升机制-轻量" tabindex="-1">晋升机制（轻量） <a class="header-anchor" href="#晋升机制-轻量" aria-label="Permalink to &quot;晋升机制（轻量）&quot;">​</a></h2><ol><li>error / learning 轨道同一 Pattern 复现 ≥3 次 → 提炼为 playbook 单文件，原条目标 <code>promoted</code>；</li><li>playbook 高频复用 → <code>status: promoted</code>，正文持续打磨；</li><li>广泛适用的认知 → 同步写入 agent memory，本仓库保留完整版。</li></ol><p>条目规模显著增长后，可升级到 <code>skills/self-improving-agent/</code> 完整体系（ID 状态机 / hook / 晋升流水线）。</p><h2 id="与-agent-memory-的分工" tabindex="-1">与 agent memory 的分工 <a class="header-anchor" href="#与-agent-memory-的分工" aria-label="Permalink to &quot;与 agent memory 的分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>本仓库</th><th>agent memory</th></tr></thead><tbody><tr><td>内容</td><td>提示词、实战手册、错误教训</td><td>用户偏好、项目约定、会话状态</td></tr><tr><td>使用者</td><td>人主动用，agent 按 INDEX 检索</td><td>agent 自动使用</td></tr><tr><td>存储形态</td><td>git 仓库，跨工具跨机器共享</td><td>单工具内持久化</td></tr></tbody></table><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><ul><li>v1 全局规则（2026-08-21 ~ 08-25）：<code>archive/rules/auto-changelog-v1.md</code></li><li>v1 元提示词（已被 WORKFLOW.md 取代）：<code>prompts/auto-changelog.md</code></li><li>现行权威契约：<a href="./WORKFLOW">WORKFLOW.md</a>（v2，2026-08-25 起）</li></ul>`,21)])])}const m=a(n,[["render",r]]);export{g as __pageData,m as default};
